target.css:
:root {
  --cream: #f7f0dc;
  --green-dark: #3a5a40;
  --green-mid: #6a9a6e;
  --green-light: #c8dfc9;
  --amber: #d48b2e;
  --text-dark: #1e2d1f;
  --text-muted: #6b7c6c;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.jar-label {
  background-color: var(--cream);
  border: 3px solid var(--green-dark);
  border-radius: 12px;
  width: 280px;
  padding: 20px 24px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.label-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.batch-num {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--green-dark);
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--amber);
  border: 2px solid var(--green-dark);
}

.jar-name {
  font-size: 28px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--text-dark);
  margin: 0;
  border-bottom: 2px dashed var(--green-mid);
  padding-bottom: 12px;
}

.label-footer {
  display: flex;
  align-items: center;
  gap: 0;
  background-color: var(--green-light);
  border-radius: 8px;
  padding: 10px 8px;
}

.footer-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.divider {
  width: 1px;
  height: 36px;
  background-color: var(--green-mid);
}

.meta-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.meta-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-dark);
}

